import React,{useEffect,useState} from 'react';
import {newKindling,kindlingActions,stepKindling,kindlingFinal,newBondstone,stepBondstone,newOverswing,stepOverswing,overswingActions,overswingPayout,signed,newUndertow,stepUndertow,undertowScore,undertowCheckOdds,rank,suit,label,bondSuits,tideSuits,tideLabel} from './engines.js';
import './external.css';
import OverswingPlay from './OverswingPlay.jsx';
const names={kindling:'Kindling',overswing:'Overswing',bondstone:'Bondstone',undertow:'Undertow'};
const fresh=(slug,mode='short')=>slug==='kindling'?newKindling():slug==='bondstone'?newBondstone():slug==='overswing'?newOverswing({mode}):newUndertow();
function Card({id,onClick,selected=false,disabled=false,symbols,note}){return <button type="button" className={'ext-card '+(selected?'chosen':'')+(id==null?'':(['♥','♦'].includes((symbols||['♥','♦','♠','♣'])[suit(id)])?' ext-red':' ext-black'))} onClick={onClick} disabled={disabled} aria-pressed={selected}><strong>{id==null?'·':label(id,symbols)}</strong>{note&&<small>{note}</small>}</button>}
function Stat({label,value}){return <div className="ext-stat"><span>{label}</span><strong>{value}</strong></div>}
function Button({children,onClick,disabled=false,primary=false}){return <button className={'ext-action '+(primary?'ext-primary':'')} disabled={disabled} onClick={onClick} type="button">{children}</button>}
function Kindling({s,act}){const [market,setMarket]=useState(0);const actions=kindlingActions(s);const chosen=actions.filter(a=>a.market===market);const find=(fire,kindle)=>chosen.find(a=>a.fire===fire&&a.kindle===kindle);return <><div className="ext-stats"><Stat label="Takes" value={`${s.turn}/40`}/><Stat label="Score" value={s.score}/><Stat label="Sparks" value={s.sparks}/><Stat label="Final value" value={kindlingFinal(s)}/></div><p className="ext-tip">Take the left market card free, or pay a Spark for either other slot. Build ascending ranks (+1 to +3). At three cards, Kindle for n² points—double when the last suit matches the first!</p><h3 className="ext-label">MARKET · CHOOSE A CARD</h3><div className="ext-market">{s.market.map((c,k)=><Card key={c} id={c} selected={market===k} disabled={k>0&&s.sparks<1} onClick={()=>setMarket(k)} note={k===0?'FREE':'1 SPARK'}/>)}</div><h3 className="ext-label">THREE FIRES</h3><div className="ext-fires">{s.fires.map((f,i)=>{const a=find(i,false),b=find(i,true);return <section className="ext-fire" key={i}><h3>FIRE {['A','B','C'][i]} <small>{f?`Top ${f.top}`:'Empty'}</small></h3><div className="ext-minicards">{f?f.cards.map((c,k)=><span key={k}>{label(c)}</span>):<em>Start a fire</em>}</div><div className="ext-buttons"><Button disabled={!a} onClick={()=>{act(a);setMarket(0)}}>{a?.smother?'Smother':'Place'}</Button><Button primary disabled={!b} onClick={()=>{act(b);setMarket(0)}}>Kindle</Button></div></section>})}</div>{s.status==='over'&&<div className="ext-result">Final: {kindlingFinal(s)} · {kindlingFinal(s)>=200?'Masterful':kindlingFinal(s)>=130?'Win':'Ash'}</div>}</>}
function Bondstone({s,act}){return <><div className="ext-stats"><Stat label="Turn" value={`${Math.min(s.t+1,40)}/40`}/><Stat label="Score" value={s.score}/><Stat label="Rise" value={`×${s.rise}`}/><Stat label="Mortar" value={s.mortar}/></div><p className="ext-tip">Place a Stone into an empty cell. A full row or column scores if the cards share a suit or form a consecutive run; a Fault cracks your Rise to ×1. Completed lines clear immediately.</p><h3 className="ext-label">STONE + TWO PREVIEWS</h3><div className="ext-market">{s.deck.slice(s.t,s.t+3).map((c,i)=><Card id={c} key={i} symbols={bondSuits} note={i===0?'STONE':`NEXT ${i}`}/>)}</div><h3 className="ext-label">3×3 WALL</h3><div className="ext-wall">{s.wall.map((c,i)=><Card key={i} id={c} symbols={bondSuits} disabled={c!=null||s.status==='over'} onClick={()=>act({type:'set',cell:i})} note={c==null?`CELL ${i+1}`:''}/>)}</div><div className="ext-buttons"><Button disabled={s.mortar===0||s.status==='over'} onClick={()=>act({type:'mortar'})}>Mortar this Stone ({s.mortar})</Button></div>{s.status==='over'&&<div className="ext-result">Final score: {s.score} · {s.score>=1000?'Masterful':s.score>=700?'Win':'Rubble'}</div>}</>}
function Undertow({s,act}){const [role,setRole]=useState('row');const [b,setB]=useState(null),[anchor,setAnchor]=useState(null),[row,setRow]=useState([]),[keep,setKeep]=useState([]);const current=s.tide[Math.min(s.turn,11)],ts=Math.floor(current/3);const chosen=c=>b===c?'BREAK':anchor===c?'ANCHOR':row.includes(c)?'ROW':null;function choose(c){const was=chosen(c);setB(x=>x===c?null:x);setAnchor(x=>x===c?null:x);setRow(x=>x.filter(v=>v!==c));if(was===role.toUpperCase())return;if(role==='break'&&suit(c)===ts)setB(c);else if(role==='anchor')setAnchor(c);else if(role==='row'&&(row.length<3||row.includes(c)))setRow(x=>[...x.filter(v=>v!==c),c]);}
 const line=s.line.length+(anchor!==null?1:0),margin=row.reduce((v,c)=>v+rank(c),0)+line-(b===null?11+current%3:0)-(s.turn+1);const odds=undertowCheckOdds(s,Math.max(6,s.strain-Math.min(0,margin)));const apply=()=>{act({type:'act',breakCard:b,anchorCard:anchor,row});setB(null);setAnchor(null);setRow([]);setKeep([]);};return <><div className="ext-stats"><Stat label="Tide" value={`${Math.min(s.turn+1,12)}/12`}/><Stat label="Catch" value={s.catch}/><Stat label="Strain / Deep" value={`${s.strain}/${s.deep}`}/><Stat label="Score" value={undertowScore(s)}/></div><p className="ext-tip">Break with one matching-suit card; Anchor one for permanent Line; Row with up to three to beat the Tide. Strain 6+ triggers a dangerous Check. Survived live checks make Strain worth double.</p><div className="ext-tide"><b>{tideLabel(current)}</b><span>Next: {s.turn<11?tideLabel(s.tide[s.turn+1]):'Final tide'} · Line +{s.line.length}{s.stage==='act'&&<small>Planned margin: {margin} · Check danger up to {Math.round(odds.prob*100)}%</small>}</span></div>{s.stage==='act'&&<div className="ext-tabs">{[['break','BREAK'],['anchor','ANCHOR'],['row','ROW ≤3'],['clear','REMOVE']].map(([key,v])=><button key={key} className={role===key?'active':''} onClick={()=>setRole(key)}>{v}</button>)}</div>}<h3 className="ext-label">{s.stage==='keep'?'KEEP UP TO FOUR CARDS':'ASSIGN YOUR CREW'}</h3><div className="ext-market">{s.hand.map(c=><Card key={c} id={c} symbols={tideSuits} selected={s.stage==='keep'?keep.includes(c):!!chosen(c)} disabled={s.stage==='keep'&&s.forceEmptyKeep} onClick={()=>s.stage==='act'?choose(c):setKeep(x=>x.includes(c)?x.filter(y=>y!==c):x.length<4?[...x,c]:x)} note={s.stage==='keep'?(keep.includes(c)?'KEEP':'DISCARD'):(chosen(c)||'AVAILABLE')}/>)}</div><div className="ext-buttons">{s.stage==='act'?<Button primary onClick={apply}>ROW! · margin {margin}</Button>:s.stage==='keep'?<Button primary onClick={()=>{act({type:'keep',cards:keep});setKeep([])}}>{s.forceEmptyKeep?'Accept forced discard':`Keep ${keep.length} and continue`}</Button>:null}</div>{s.stage==='keep'&&s.lastResult?.cracked&&<div className="ext-warning">CRACK! Catch was halved and Strain/Deep reset.{s.forceEmptyKeep?' The early Crack also discards your hand.':''}</div>}{s.status==='over'&&<div className="ext-result">Final score: {undertowScore(s)} · {undertowScore(s)>=165?'Masterful':undertowScore(s)>=140?'Win':'Survived'}</div>}</>}
export default function ExternalPlay({game}){const slug=game.slug,key=`card-game-lab.external.${slug}.${slug==='overswing'?'v9':'v1'}`;const [s,setS]=useState(()=>{try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&saved.game===slug&&saved.status&&(slug!=='overswing'||saved.version===9))return saved;}catch{}return fresh(slug)});useEffect(()=>{try{localStorage.setItem(key,JSON.stringify(s));}catch{}},[s,key]);const act=a=>{if(!a)return;setS(old=>slug==='kindling'?stepKindling(old,a):slug==='bondstone'?stepBondstone(old,a):slug==='overswing'?stepOverswing(old,a):stepUndertow(old,a));};const restart=mode=>setS(fresh(slug,mode||s.mode));return <div className={slug==='overswing'?'ext-play ext-overswing-wrap':'ext-play'}><header className="ext-header"><div><span>GUEST LAB · PLAYABLE PROTOTYPE</span><h1>{names[slug]}</h1></div><button onClick={()=>restart()}>↻ New game</button></header>{slug==='kindling'?<Kindling s={s} act={act}/>:slug==='overswing'?<OverswingPlay s={s} act={act} restart={restart}/>:slug==='bondstone'?<Bondstone s={s} act={act}/>:<Undertow s={s} act={act}/>}<p className="ext-message" role="status">{s.last}</p><details className="ext-log"><summary>Recent actions</summary>{s.history?.map((h,i)=><p key={i}>{h}</p>)}</details><p className="ext-footnote">These are interactive browser implementations of the provided final specifications. Local scores are not equivalent to the reference Python-seed simulations.</p></div>}
